import esbuild from "esbuild";
import builtins from "builtin-modules";
import process from "node:process";

const production = process.argv[2] === "production";

const banner = `/*
 * obs-harness — generated by esbuild. Edit src/ or server/ instead.
 */`;

/** Obsidian plugin bundle: runs in the Electron renderer. */
const pluginOptions = {
  entryPoints: ["src/main.ts"],
  outfile: "main.js",
  bundle: true,
  format: "cjs",
  target: "es2022",
  platform: "browser",
  logLevel: "info",
  sourcemap: production ? false : "inline",
  treeShaking: true,
  minify: production,
  banner: { js: banner },
  external: [
    "obsidian",
    "electron",
    "@codemirror/autocomplete",
    "@codemirror/collab",
    "@codemirror/commands",
    "@codemirror/language",
    "@codemirror/lint",
    "@codemirror/search",
    "@codemirror/state",
    "@codemirror/view",
    "@lezer/common",
    "@lezer/highlight",
    "@lezer/lr",
    ...builtins,
    ...builtins.map((m) => `node:${m}`),
  ],
};

/** Bridge server bundle: standalone node script, ws bundled in. */
const serverOptions = {
  entryPoints: ["server/src/index.ts"],
  outfile: "server.js",
  bundle: true,
  format: "cjs",
  target: "node20",
  platform: "node",
  logLevel: "info",
  sourcemap: production ? false : "inline",
  minify: false,
  banner: { js: `#!/usr/bin/env node\n${banner}` },
  external: [...builtins, ...builtins.map((m) => `node:${m}`), "bufferutil", "utf-8-validate"],
};

if (production) {
  await Promise.all([esbuild.build(pluginOptions), esbuild.build(serverOptions)]);
  process.exit(0);
}

const contexts = await Promise.all([
  esbuild.context(pluginOptions),
  esbuild.context(serverOptions),
]);
await Promise.all(contexts.map((ctx) => ctx.watch()));
console.log("[obs-harness] watching src/ and server/ …");
